package cli_test

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestCLICommands(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantExit   int
		wantStdout string
		wantStderr string
	}{
		// Command parsing
		{"init creates config", []string{"init"}, 0, "initialized", ""},
		{"get requires key", []string{"get"}, 2, "", "usage"},
		{"get existing key", []string{"get", "foo"}, 0, "bar", ""},
		{"get missing key", []string{"get", "nonexistent"}, 1, "", "not found"},
		{"set requires key and value", []string{"set"}, 2, "", "usage"},
		{"set key value", []string{"set", "foo", "bar"}, 0, "", ""},
		{"delete requires key", []string{"delete"}, 2, "", "usage"},
		{"delete existing", []string{"delete", "foo"}, 0, "", ""},
		{"delete missing", []string{"delete", "nonexistent"}, 1, "", "not found"},
		{"validate valid config", []string{"validate"}, 0, "valid", ""},
		{"list empty", []string{"list"}, 0, "", ""},
		{"unknown command", []string{"unknown"}, 2, "", "unknown command"},

		// Flags
		{"config flag", []string{"--config", "/tmp/test.yaml", "list"}, 0, "", ""},
		{"format json", []string{"--format", "json", "list"}, 0, "[]", ""},
		{"format yaml", []string{"--format", "yaml", "list"}, 0, "", ""},
		{"format invalid", []string{"--format", "xml", "list"}, 2, "", "invalid format"},
		{"quiet suppresses output", []string{"--quiet", "set", "a", "b"}, 0, "", ""},
		{"verbose shows debug", []string{"--verbose", "list"}, 0, "", ""},

		// Edge cases
		{"no args shows help", []string{}, 2, "", "usage"},
		{"help flag", []string{"--help"}, 0, "usage", ""},
		{"empty key rejected", []string{"set", "", "value"}, 2, "", "empty key"},
		{"key with spaces", []string{"set", "key with spaces", "val"}, 0, "", ""},
		{"value with special chars", []string{"set", "k", "val=ue"}, 0, "", ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			exit := runCLI(tt.args, stdout, stderr)

			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
			if tt.wantStdout != "" && !bytes.Contains(stdout.Bytes(), []byte(tt.wantStdout)) {
				t.Errorf("stdout = %q, want containing %q", stdout, tt.wantStdout)
			}
			if tt.wantStderr != "" && !bytes.Contains(stderr.Bytes(), []byte(tt.wantStderr)) {
				t.Errorf("stderr = %q, want containing %q", stderr, tt.wantStderr)
			}
		})
	}
}

func TestFileOperations(t *testing.T) {
	tests := []struct {
		name     string
		setup    func(dir string)
		args     []string
		wantExit int
	}{
		{"init in empty dir", nil, []string{"init"}, 0},
		{"init existing fails", func(d string) { os.WriteFile(filepath.Join(d, "config.yaml"), []byte{}, 0644) }, []string{"init"}, 1},
		{"read missing config", nil, []string{"--config", "/nonexistent/path", "list"}, 1},
		{"read unreadable config", func(d string) { os.WriteFile(filepath.Join(d, "c.yaml"), []byte{}, 0000) }, []string{"--config", "c.yaml", "list"}, 1},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir := t.TempDir()
			if tt.setup != nil {
				tt.setup(dir)
			}
			exit := runCLI(tt.args, nil, nil)
			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
		})
	}
}
